mapper.sql:
WHERE ps.performance_id = #{condition.performanceId}


  AND (
  s.section_name LIKE CONCAT(
  '%',
  #{condition.keyword},
  '%'
  )
  OR s.row_name LIKE CONCAT(
  '%',
  #{condition.keyword},
  '%'
  )
  OR s.seat_number LIKE CONCAT(
  '%',
  #{condition.keyword},
  '%'
  )
  )



  AND s.floor = #{condition.floor}



  AND ps.grade = #{condition.grade}



  AND s.seat_type = #{condition.seatType}



  AND ps.status = #{condition.status}
